INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em um paciente com empiema organizado (espessamento pleural denso - ''Casca Pleural''), por que o uso de fibrinolíticos ou dreno de tórax simples costuma falhar?", "options": {"a": "Porque as bactérias são resistentes aos antibióticos dentro da casca.", "b": "Porque a pleura visceral desaparece.", "c": "Porque o pulmão está ''aprisionado'' por uma membrana de tecido fibroso denso que impede sua reexpansão (Pulmão Encarcerado), mesmo que o líquido seja retirado.", "d": "Porque o pus se transforma em gordura.", "e": "Porque o dreno causa mais infecção."}, "answer": "c", "rationale": "Na fase organizada do empiema (Fase 3), a deposição de colágeno e fibroblastos cria uma carapaça rígida sobre a pleura visceral. Isso impede o pulmão de inflar e encostar na parede torácica. O problema aqui é mecânico, exigindo decorticação cirúrgica para retirar a casca e liberar o pulmão.", "option_rationales": {"a": "Incorreta. Embora a penetração do atb seja ruim, o problema principal para a resolução radiológica é a falta de expansão pulmonar.", "b": "Incorreta. A pleura visceral está espessada, não ausente.", "c": "Correta. Definição fisiopatológica do pulmão encarcerado sequelar ao empiema.", "d": "Incorreta. Pus não vira gordura.", "e": "Incorreta. O dreno é necessário, mas insuficiente na fase fibrótica crônica."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia Torácica", "Empiema", "Pulmão Encarcerado"]}', 0, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 45 anos é diagnosticado com derrame pleural parapneumônico. Durante a toracentese diagnóstica, observa-se líquido turvo, pH de 7,12, glicose de 35 mg/dL e LDH de 1200 U/L. A coloração de Gram foi negativa para microrganismos. Com base nas recomendações atuais de manejo da pleura, a melhor conduta imediata para este paciente é:", "options": {"a": "Pleurodese química com talco para evitar a recorrência do derrame.", "b": "Toracostomia com drenagem pleural tubular em selo d''água.", "c": "Realização de toracocinese de alívio repetida a cada 24 horas.", "d": "Apenas antibioticoterapia venosa, postergando a drenagem devido ao Gram negativo.", "e": "Encaminhamento imediato para decorticação pulmonar por toracotomia."}, "answer": "b", "rationale": "Achados de pH < 7,20, glicose < 40-60 mg/dL ou LDH > 1000 U/L em um derrame parapneumônico indicam um exsudato ''complicado'', mesmo com Gram negativo. Nesses casos, a drenagem pleural imediata é mandatória para evitar a evolução para empiema organizado e encarceramento pulmonar.", "option_rationales": {"a": "Incorreta. A pleurodese é contraindicada em infecções pleurais agudas.", "b": "Correta. Critérios bioquímicos de complicação (pH < 7,2 e glicose baixa) indicam drenagem tubular.", "c": "Incorreta. Toracocenteses repetidas não são eficazes para derrames parapneumônicos complicados.", "d": "Incorreta. O pH baixo e a glicose consumida exigem drenagem, independentemente do Gram.", "e": "Incorreta. A decorticação é uma medida tardia para casos organizados onde a drenagem falhou."}, "difficulty": "dificil", "tags": ["Pneumologia", "Derrame Pleural Complicado", "Conduta", "Drenagem"]}', 1, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico de Tuberculose Pleural, qual a principal desvantagem do teste rápido molecular (GeneXpert / TRM-TB) no LÍQUIDO pleural em comparação ao escarro?", "options": {"a": "Não detecta resistência à rifampicina.", "b": "Só funciona em urina.", "c": "É muito caro.", "d": "Tem baixa sensibilidade (< 50%) devido à natureza paucibacilar do derrame pleural tuberculoso, embora sua especificidade seja alta.", "e": "Causa falsos-positivos com bactérias da pneumonia."}, "answer": "d", "rationale": "Embora o GeneXpert seja excelente para escarro (onde há muitos bacilos), no líquido pleural a carga bacteriana é tão baixa que o teste muitas vezes não consegue detectar o DNA do Mycobacterium. Por isso, um TRM-TB negativo no líquido NÃO exclui TB pleural.", "option_rationales": {"a": "Incorreta. Detecta resistência se houver material genético suficiente.", "b": "Incorreta.", "c": "Incorreta.", "d": "Correta. Limitação técnica importante para o clínico saber interpretar.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Infectologia", "TRM-TB", "GeneXpert"]}', 2, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 70 anos apresenta derrame pleural volumoso à direita. A análise do líquido revela: Exsudato hemorrágico, com citologia oncótica positiva para adenocarcinoma. A tomografia mostra múltiplas metástases hepáticas e cerebrais. O controle das metástases cerebrais é priorizado, mas o paciente apresenta dispneia importante pelo derrame. Qual o manejo paliativo MAIS ADEQUADO para o derrame pleural neste cenário de doença avançada?", "options": {"a": "Inserção de cateter pleural de demora (IPC) para drenagem domiciliar.", "b": "Radioterapia sobre o hemitórax direito.", "c": "Pleurodese com talco via toracotomia.", "d": "Toracocenteses de alívio diárias no hospital.", "e": "Quimioterapia sistêmica isolada, sem intervenção pleural."}, "answer": "a", "rationale": "O cateter pleural de demora (IPC) é excelente para pacientes com câncer avançado, curta expectativa de vida e sintomas de dispneia recorrente. Ele permite que o paciente seja tratado em casa, reduzindo o tempo de hospitalização e sendo menos invasivo que a pleurodese por drenagem tubular ou cirúrgica.", "option_rationales": {"a": "Correta. Padrão paliativo moderno para qualidade de vida domiciliar.", "b": "Incorreta. Radioterapia não trata o derrame volumoso agudo.", "c": "Incorreta. Muito agressivo e exige internação prolongada.", "d": "Incorreta. Toracocenteses repetidas causam alto desconforto e risco de infecção.", "e": "Incorreta. A quimio demora a agir; o alívio imediato da dispneia exige drenagem."}, "difficulty": "facil", "tags": ["Pneumologia", "Oncologia", "Palhação", "Cateter Pleural"]}', 3, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal limitação da biópsia pleural por agulha ''cega'' (e.g., Abrams) no diagnóstico do Mesotelioma Maligno?", "options": {"a": "A agulha de Abrams só pode ser usada na pleura visceral.", "b": "O talco nas luvas do patologista impede o diagnóstico.", "c": "O mesotelioma acomete a pleura de forma focal/nodular no início, e a biópsia cega pode captar apenas áreas de pleurite inflamatória reativa entre os nódulos tumorais.", "d": "O mesotelioma não é visível no microscópio comum.", "e": "A agulha é grossa demais e causa pneumotórax sempre."}, "answer": "c", "rationale": "Assim como o adenocarcinoma pleural, o mesotelioma pode crescer em placas ou nódulos. A biópsia cega tem um ''erro de amostragem'' inerente. Um resultado negativo em biópsia cega não exclui o diagnóstico, exigindo biópsia dirigida por imagem ou por VATS se a suspeita persistir.", "option_rationales": {"a": "Incorreta. Abrams biópsia exclusivamente pleura parietal.", "b": "Incorreta. Não interfere.", "c": "Correta. Limitação fundamental da técnica cega em patologias nodulares.", "d": "Incorreta. É visível sim.", "e": "Incorreta. Risco de pneumotórax existe, mas não é a limitação diagnóstica principal (biológica)."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Mesotelioma", "Biópsia Cega"]}', 4, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Na análise do líquido pleural, um exsudato com predomínio de linfócitos e ADA elevado, mas que apresenta ABSÊNCIA total de células mesoteliais (< 5%), é altamente sugestivo de qual patologia?", "options": {"a": "Lúpus Eritematoso Sistêmico.", "b": "Pneumonia Atípica.", "c": "Carcinoma de Células Pequenas.", "d": "Tuberculose Pleural.", "e": "Mesotelioma."}, "answer": "d", "rationale": "A inflamação granulomatosa da pleura na tuberculose causa um intenso espessamento e recobrimento da pleura visceral por fibrina e colágeno, o que impede que as células mesoteliais (que revestem a pleura) descamem para o líquido. Por isso, a escassez ou ausência de mesoteliais é uma pista citológica clássica de TB pleural.", "option_rationales": {"a": "Incorreta. No lúpus as mesoteliais podem ser normais ou até aumentadas e atípicas.", "b": "Incorreta. Não apresenta esse padrão inibitório.", "c": "Incorreta. Pode haver mesoteliais na carcinomatose secundária.", "d": "Correta. Dado clássico de citopatologia pleural.", "e": "Incorreta. Mesoteliomas apresentam muitas células mesoteliais (as próprias células neoplásicas)."}, "difficulty": "dificil", "tags": ["Pneumologia", "Tuberculose", "Citopatologia", "Mesoteliais"]}', 5, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ocorrência de derrame pleural com característica de exsudato, em paciente com história de febre, emagrecimento, dor torácica e achado de amilase pleural elevada (maior que o limite superior da amilase sérica), direciona o raciocínio clínico prioritariamente para os seguintes diferenciais, EXCETO:", "options": {"a": "Tuberculose pleural em fase inicial.", "b": "Adenocarcinoma de pâncreas com metástase pleural.", "c": "Pancreatite aguda ou crônica (pseudoqueisto pancreático).", "d": "Neoplasia de pulmão ou ovário (adenocarcinoma).", "e": "Ruptura esofágica (Síndrome de Boerhaave)."}, "answer": "a", "rationale": "A amilase pleural elevada é encontrada tipicamente em quatro condições: doenças pancreáticas, ruptura esofágica (salivar), neoplasias (amilase isoforma salivar) e, raramente, gravidez ectópica rota. A tuberculose pleural, embora cause exsudato linfocítico, classicamente não cursa com elevação de amilase no líquido pleural.", "option_rationales": {"a": "Correta. A Tuberculose Pleural não está associada à elevação de amilase pleural.", "b": "Incorreta. Metástases de adenocarcinoma pancreático seguem a lógica de doenças pancreáticas.", "c": "Incorreta. Pancreatite é uma causa clássica de derrame com amilase alta.", "d": "Incorreta. Cerca de 10% das neoplasias malignas pleurais podem elevar a amilase.", "e": "Incorreta. Ruptura esofágica cursa com amilase muito alta (origem salivar)."}, "difficulty": "dificil", "tags": ["Pneumologia", "Derrame Pleural", "Amilase Pleural", "Diagnóstico Diferencial"]}', 6, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 35 anos apresenta quadro de febre, perda de peso e sudorese noturna há 1 mês. RX de tórax com derrame pleural bilateral e múltiplos nódulos pulmonares de 2-4 mm (padrão miliar). A análise do líquido pleural revela exsudato linfocítico, ADA de 20 U/L. O Teste Rápido Molecular (TRM-TB) no líquido foi negativo. Qual o achado mais provável que explicaria um ADA baixo em um quadro clínico tão sugestivo de Tuberculose?", "options": {"a": "Tuberculose Miliar com disseminação pleural secundária em paciente imunodeprimido.", "b": "Tuberculose Pleural em paciente imunocompetente.", "c": "Linfoma de Hodgkin mimetizando TB.", "d": "Adenocarcinoma de pulmão estágio IV.", "e": "Coccidioidomicose pulmonar."}, "answer": "a", "rationale": "Enquanto a Tuberculose Pleural isolada (por hipersensibilidade tardia) cursa com ADA muito alto, a Tuberculose Miliar que envolve a pleura pode apresentar derrames com ADA baixo ou limítrofe, especialmente em pacientes com HIV ou imunossupressão grave, devido à falha na resposta imune celular exuberante que eleva o ADA.", "option_rationales": {"a": "Correta. A forma miliar e o status imune podem ''falsear'' o ADA para baixo.", "b": "Incorreta. TB pleural clássica tem ADA > 40 invariavelmente.", "c": "Incorreta. Embora possível, o quadro miliar favorece TB.", "d": "Incorreta. O padrão miliar é diferente da carcinomatose linfangítica típica.", "e": "Incorreta. Fungos podem dar ADA baixo, mas a TB miliar é a causa clássica de ADA falso-baixo no contexto infeccioso disseminado."}, "difficulty": "dificil", "tags": ["Pneumologia", "Infectologia", "Tuberculose Miliar", "ADA"]}', 7, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente idoso, hígido até o momento, apresenta quadro de dor torácica súbita e derrame pleural hemorrágico à direita. A tomografia revela ruptura de um pequeno ramo de artéria intercostal sem história de trauma evidente. Este fenômeno é conhecido como:", "options": {"a": "Hemotórax Idiopático.", "b": "Hemotórax por Fragilidade Capilar Senil.", "c": "Aneurisma de artéria intercostal roto espontaneamente.", "d": "Dissecção aórtica tipo B.", "e": "Hemotórax espontâneo por esforço (咳嗽)."}, "answer": "c", "rationale": "Aneurismas verdadeiros ou pseudoaneurismas das artérias intercostais podem romper espontaneamente (ou após tosse vigorosa), causando hemotórax maciço sem trauma. O diagnóstico é angiográfico e o tratamento pode ser por embolização transcateter ou cirurgia.", "option_rationales": {"a": "Incorreta. Sempre deve-se buscar a causa vascular oculta.", "b": "Incorreta. Termo técnico inexistente nesta patologia.", "c": "Correta. Causa importante de hemotórax não traumático em idosos.", "d": "Incorreta. Dissecção de aorta causa outros achados na TC, embora também possa dar hemotórax (geralmente à esquerda).", "e": "Incorreta. Termo não padronizado para esta etiologia específica."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia Vascular", "Hemotórax Espontâneo"]}', 8, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente diagnosticado com Tuberculose Pleural (biópsia positiva). Inicia esquema RIPE. Após 15 dias de tratamento, apresenta aumento do volume do derrame pleural e febre leve, apesar de melhora do estado geral. Qual a interpretação correta?", "options": {"a": "Falência terapêutica por resistência às drogas de primeira linha.", "b": "Reação Paradoxal (efeito de reconstituição imune local).", "c": "Contaminação bacteriana secundária do derrame (Empiema pós-toracentese).", "d": "Desenvolvimento de Linfoma associado à TB.", "e": "Toxicidade hepática pela pirazinamida causando ascite translocada."}, "answer": "b", "rationale": "A ''Reação Paradoxal'' na TB pleural ocorre quando a carga bacilar cai pela medicação, mas a resposta inflamatória imune aumenta transitoriamente (pela exposição de antígenos bacilares), levando à piora radiológica ou do derrame. Se o paciente está clinicamente bem, a conduta é apenas observação e manutenção do RIPE.", "option_rationales": {"a": "Incorreta. Muito cedo para diagnosticar falha se houver melhora clínica.", "b": "Correta. Fenômeno autoimune reativo clássico pós-início de RIPE.", "c": "Incorreta. Possível, mas a reação paradoxal é mais comum se o dreno não estiver lá.", "d": "Incorreta. Improvável.", "e": "Incorreta. Toxicidade hepática causa dor e náuseas, não aumento isolado do derrame pleural em 15 dias sem ascite volumosa prévia."}, "difficulty": "media", "tags": ["Pneumologia", "Tuberculose", "Terapêutica", "Reação Paradoxal"]}', 9, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Para o diagnóstico de Chilotórax, a dosagem de triglicerídeos no líquido pleural é o teste inicial de escolha. No entanto, em valores intermediários (entre 50 e 110 mg/dL), qual exame adicional é mandatório para confirmar a presença de quilo no espaço pleural?", "options": {"a": "Pesquisa de Quilomícrons por eletroforese de lipoproteínas.", "b": "Contagem de Eosinófilos no líquido.", "c": "Linfocintilografia de membros inferiores.", "d": "Dosagem de Colesterol Pleural.", "e": "Relação Creatinina Pleural / Sérica."}, "answer": "a", "rationale": "Valores de TG > 110 mg/dL confirmam quilotórax; < 50 mg/dL praticamente excluem. No ''limbo'' entre 50-110 mg/dL, a presença de quilomícrons na eletroforese do líquido pleural é o padrão-ouro para o diagnóstico confirmatório.", "option_rationales": {"a": "Correta. Exame definitivo para casos com TG inconclusivo.", "b": "Incorreta. Não tem relação com o quilo.", "c": "Incorreta. Pode ser usada para localizar a fístula, mas não para o diagnóstico bioquímico inicial do líquido.", "d": "Incorreta. O colesterol ajuda no pseudoquilotórax, não na confirmação do quilo verdadeiro borderline.", "e": "Incorreta. Usado no urinotórax."}, "difficulty": "media", "tags": ["Pneumologia", "Laboratório", "Quilotórax", "Lipídios"]}', 10, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um homem de 62 anos, com antecedente de insuficiência cardíaca congestiva em uso otimizado de furosemida, apresenta-se com dispneia progressiva. A radiografia de tórax revela derrame pleural bilateral, maior à direita. Realizada toracentese diagnóstica que evidencia: Proteína pleural / Proteína sérica = 0,55; LDH pleural / LDH sérica = 0,72; LDH pleural = 240 U/L (Limite superior do soro = 300 U/L). O gradiente de albumina (Soro - Pleura) é de 1,4 g/dL. Diante desses achados, a interpretação correta do líquido pleural e a conduta mais adequada são:", "options": {"a": "Exsudato falso-positivo; realizar biópsia pleural por agulha imediatamente.", "b": "Transudato mascarado pelo uso de diuréticos; manter tratamento da patologia de base.", "c": "Exsudato pelos critérios de Light; iniciar investigação para neoplasia oculta.", "d": "Empiema em fase inicial; iniciar antibioticoterapia de amplo espectro venosa.", "e": "Quilotórax incipiente; solicitar dosagem de triglicerídeos no líquido pleural."}, "answer": "b", "rationale": "O paciente apresenta critérios de Light que sugerem exsudato (LDH pleural/sérica > 0,6), porém o contexto clínico de ICC em uso de diuréticos frequentemente causa exsudatos falso-positivos por concentração de proteínas e LDH. O gradiente de albumina soro-pleura > 1,2 g/dL confirma que o líquido é, na verdade, um transudato. A conduta correta é focar no tratamento da doença de base (ICC).", "option_rationales": {"a": "Incorreta. A biópsia não é indicada para transudatos de origem cardíaca.", "b": "Correta. O gradiente de albumina soro-pleura > 1,2 g/dL é o padrão-ouro para identificar transudatos em pacientes usando diuréticos.", "c": "Incorreta. Embora preencha critérios de Light, o gradiente de albumina desmascara o transudato por diuréticos.", "d": "Incorreta. Não há sinais clínicos ou laboratoriais (como febre ou leucocitose) que sugiram empiema.", "e": "Incorreta. O aspecto do líquido e a clínica não sugerem o acúmulo de linfa (quilotórax)."}, "difficulty": "dificil", "tags": ["Pneumologia", "Derrame Pleural", "Critérios de Light", "ICC"]}', 11, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico do Mieloma Múltiplo com acometimento pleural (Derrame Pleural por Mieloma), qual é a característica definitiva do líquido pleural?", "options": {"a": "Citologia oncótica demonstrando plasmócitos neoplásicos (> 50% das células nucleadas) e presença de componente monoclonal (pico gama) na eletroforese de proteínas do líquido.", "b": "Amilase pleural elevada.", "c": "Transudato rico em albumina.", "d": "Odor fétido e pH alto.", "e": "Presença de granulomas caseosos."}, "answer": "a", "rationale": "O envolvimento pleural direto pelo mieloma é raro (< 1% dos casos). O diagnóstico é feito pela visualização de plasmócitos atípicos no líquido e pela demonstração da proteína monoclonal (paraproteína) no próprio derrame, confirmando a infiltração plasmocitária maligna da pleura.", "option_rationales": {"a": "Correta. Critérios diagnósticos hematológicos aplicados à pleura.", "b": "Incorreta. Não associada.", "c": "Incorreta. Mieloma infiltrativo causa exsudato.", "d": "Incorreta. Indica empiema por anaeróbios.", "e": "Incorreta. Indica TB."}, "difficulty": "dificil", "tags": ["Pneumologia", "Hematologia", "Mieloma Múltiplo", "Plasmócitos"]}', 12, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual dos seguintes parâmetros no líquido pleural ajuda a distinguir com segurança o Quilotórax (linfa) do Pseudoquilotórax (coleção crônica de colesterol)?", "options": {"a": "O pH, que é alcalino apenas no pseudoquilotórax.", "b": "O ADA elevado é típico de quilotórax.", "c": "A dosagem de triglicerídeos > 110 mg/dL e a presença de quilomícrons favorecem Quilotórax.", "d": "O aspecto macroscópico, pois apenas o quilotórax é leitoso.", "e": "A presença de cristais rômbicos favorece quilotórax agudo."}, "answer": "c", "rationale": "O diagnóstico diferencial clínico/químico baseia-se nos lipídios: Quilotórax tem TG alto (> 110) e Quilomícrons. Pseudoquilotórax tem TG baixo, mas colesterol muito alto (> 200 mg/dL) e presença de cristais de colesterol (rômbicos).", "option_rationales": {"a": "Incorreta. Não é um critério de diferenciação.", "b": "Incorreta. ADA alto é de TB ou AR.", "c": "Correta. Parâmetro bioquímico confirmatório para quilo verdadeiro.", "d": "Incorreta. Ambos podem ter aspecto leitoso ou ''opalescente''.", "e": "Incorreta. Cristais de colesterol são do pseudoquilotórax crônico."}, "difficulty": "media", "tags": ["Pneumologia", "Bioquímica", "Quilotórax", "Lipídios"]}', 13, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em um paciente com pneumonia da comunidade que desenvolve derrame pleural associado, qual o achado na análise do líquido pleural que MELHOR prediz a necessidade de drenagem torácica?", "options": {"a": "ADA > 40 U/L.", "b": "Glicose pleural de 80 mg/dL.", "c": "LDH pleural > 1.000 U/L ou pH < 7,2.", "d": "Volume de derrame superior a 500 mL na radiografia.", "e": "Presença de linfócitos > 50%."}, "answer": "c", "rationale": "Os critérios bioquímicos de complicação de um derrame parapneumônico (indicadores de drenagem) são: pH < 7,20, glicose < 40-60 mg/dL, ou LDH > 1.000 U/L. A presença de pus franco ou Gram/cultura positivos também são indicações absolutas.", "option_rationales": {"a": "Incorreta. Sugere TB.", "b": "Incorreta. Glicose normal costuma indicar derrame simples.", "c": "Correta. Marcadores bioquímicos de empiema/complicado.", "d": "Incorreta. O volume isolado não decide a drenagem, mas sim a composição bioquímica/biológica.", "e": "Incorreta. Sugere TB ou neoplasia, não pneumonia bacteriana aguda."}, "difficulty": "media", "tags": ["Pneumologia", "Empiema", "Manejo", "Drenagem"]}', 14, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre a Síndrome de Meigs, assinale a alternativa que descreve CORRETAMENTE a condição.", "options": {"a": "Derrame pleural bilateral associado a lúpus discoide e artrite.", "b": "Tumor ovariano benigno (geralmente fibroma), ascite e derrame pleural.", "c": "Ascite volumosa por cirrose que transloca para a pleura esquerda.", "d": "Tumor de pulmão com invasão direta do ovário e peritônio.", "e": "Metástase ovariana de câncer gástrico (Tumor de Krukenberg) com derrame maligno."}, "answer": "b", "rationale": "A Síndrome de Meigs clássica consiste em um tumor ovariano benigno (fibroma, tecoma ou cistoadenoma), ascite e derrame pleural (mais comum à direita). O marco da síndrome é que tanto o derrame quanto a ascite desaparecem permanentemente após a remoção do tumor ovariano.", "option_rationales": {"a": "Incorreta. Não tem relação com o perfil de Meigs.", "b": "Correta. Definição clássica da síndrome.", "c": "Incorreta. Isso seria hidrotórax hepático.", "d": "Incorreta. Meigs é um tumor primário de ovário, não de pulmão.", "e": "Incorreta. Meigs exige tumor benigno."}, "difficulty": "media", "tags": ["Pneumologia", "Ginecologia", "Síndrome de Meigs"]}', 15, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente com diagnóstico de Artrite Reumatoide em atividade grave apresenta derrame pleural bilateral. Durante a análise do líquido pleural, observa-se glicose de 10 mg/dL e LDH de 1800 U/L. Assinale a alternativa que apresenta a característica citológica e laboratorial adicional que reforçaria esse diagnóstico específico.", "options": {"a": "pH do líquido pleural extremamente baixo, frequentemente < 7,00.", "b": "Presença de eosinófilos > 40% indicando hipersensibilidade.", "c": "Presença de células LE (Lúpus Eritematoso) no líquido.", "d": "Baixos níveis de Fator Reumatoide (FR) no líquido em relação ao soro.", "e": "Complemento (C3, C4) elevado no líquido pleural."}, "answer": "a", "rationale": "O derrame pleural da Artrite Reumatoide é característico por ser ''explosivo'' do ponto de vista inflamatório: glicose extremamente baixa (muitas vezes < 20 mg/dL), LDH muito alto (> 700 ou 1000) e pH muito baixo. Outros achados incluem FR elevado no líquido e presença de células multinucleadas.", "option_rationales": {"a": "Correta. O pH baixo e a glicose consumida são marcas registradas do derrame da Artrite Reumatoide.", "b": "Incorreta. Eosinofilia pleural não é típica da AR (sugere ar ou sangue na pleura).", "c": "Incorreta. Células LE são características do Lúpus, não da AR.", "d": "Incorreta. O Fator Reumatoide costuma estar elevado no líquido pleural da AR.", "e": "Incorreta. O complemento costuma estar reduzido no derrame da AR devido ao consumo."}, "difficulty": "dificil", "tags": ["Pneumologia", "Reumatologia", "Derrame Pleural", "Artrite Reumatoide"]}', 16, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A dosagem de Antígeno Carcinoembrionário (CEA) no líquido pleural apresenta qual utilidade prática no diagnóstico de adenocarcinoma de pulmão?", "options": {"a": "Identifica pacientes que responderão ao tabaco.", "b": "Valores muito elevados (ex: > 5-10 ng/mL) no líquido sugerem fortemente malignidade, aumentando a sensibilidade diagnóstica quando combinada com a citologia oncótica.", "c": "Substitui a biópsia pleural.", "d": "É o marcador específico de Tuberculose.", "e": "Indica infecção por fungos."}, "answer": "b", "rationale": "O CEA pleural não é 100% específico, mas quando elevado no líquido (acima do valor de corte laboratorial), aumenta consideravelmente a suspeita de câncer epitelial (especialmente pulmão, mama e trato digestivo), ajudando em casos onde a citologia inicial é inconclusiva.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Uso aditivo à citologia para aumentar acurácia.", "c": "Incorreta. Marcadores tumorais são auxiliares, não substitutos teciduais.", "d": "Incorreta. TB tem CEA baixo.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Marcadores Tumorais", "CEA"]}', 17, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No hemotórax traumático, o sangue no espaço pleural tende a se coagular rapidamente, o que dificulta a drenagem por cateteres finos. No entanto, por que o sangue costuma ser aspirado em estado líquido nas primeiras horas após o trauma?", "options": {"a": "O sangue pleural nunca coagula.", "b": "A desfibrinação do sangue ocorre pelos movimentos respiratórios e cardíacos, transformando o fibrinogênio em fibrina que se deposita nas superfícies pleurais.", "c": "As bactérias pleurais consomem as plaquetas.", "d": "O líquido pleural transuda água para o sangue, diluindo os fatores de coagulação.", "e": "O pulmão produz heparina natural em doses cavalares."}, "answer": "b", "rationale": "O sangue no espaço pleural sofre um processo de desfibrinação mecânica por agitação física do coração e pulmões. A fibrina precipita-se sobre a pleura e o líquido remanescente (soro sanguineo) permanece incoagulável in vitro. Se o sangramento for maciço e rápido, o sistema de desfibrinação falha, formando coágulos sólidos que bloqueiam drenos.", "option_rationales": {"a": "Incorreta. Coagula sim, e pode gerar empiema coagulado/pseudotumor hemático.", "b": "Correta. Fenômeno fisiopatológico do hemotórax.", "c": "Incorreta. Não ocorre em condições traumáticas imediatas.", "d": "Incorreta. Pelo contrário, o sangue irrita a pleura e gera exsudato adicionando proteína.", "e": "Incorreta. Explicação fictícia."}, "difficulty": "dificil", "tags": ["Pneumologia", "Fisiopatologia", "Hemotórax", "Coagulação"]}', 18, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A causa mais comum de quilotórax traumático (latrogênico) é a cirurgia torácica. Qual procedimento cirúrgico apresenta o maior risco histórico de lesão do ducto torácico?", "options": {"a": "Timectomia por via esternal.", "b": "Revascularização do miocárdio.", "c": "Drenagem de abscesso pulmonar.", "d": "Pneumonectomia devido a câncer.", "e": "Esofagectomia."}, "answer": "e", "rationale": "Devido à íntima proximidade anatômica entre o esôfago e o ducto torácico no mediastino posterior, as esofagectomias representam a principal causa cirúrgica de quilotórax iatrogênico.", "option_rationales": {"a": "Incorreta. Mediastino anterior não hospeda o ducto torácico em seu trajeto principal.", "b": "Incorreta. O ducto é posterior e a CRM é anterior/medial.", "c": "Incorreta. Procedimento geralmente periférico.", "d": "Incorreta. Risco existe, mas menor que na esofagectomia.", "e": "Correta. Causa clássica de lesão do ducto."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia Torácica", "Quilotórax iatrogênico"]}', 19, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente em diálise peritoneal ambulatorial desenvolve dispneia súbita e derrame pleural maciço à direita. Suspeita-se de ''Hidrotórax Doce'' (fístula pleuroperitoneal). Qual o parâmetro laboratorial no líquido pleural que confirma este diagnóstico com maior precisão?", "options": {"a": "ADA elevado e linfocitose.", "b": "Presença de células de descamação pleural (mesoteliais).", "c": "Presença de cristais de colesterol no líquido.", "d": "Glicose pleural significativamente MAIOR que a glicose sérica.", "e": "Proteína pleural superior a 3,0 g/dL."}, "answer": "d", "rationale": "No hidrotórax secundário à diálise peritoneal, o líquido que vaza para a pleura é o próprio dialisado, que possui uma concentração de glicose altíssima. Assim, encontrar glicose pleural muito superior à sérica (ex: 200, 300 mg/dL ou mais) é diagnóstico da fístula pleuroperitoneal.", "option_rationales": {"a": "Incorreta. Sugere TB e não tem relação com diálise.", "b": "Incorreta. Não é específico, qualquer derrame ascitogênico pode ter.", "c": "Incorreta. Sugere pseudochylothorax crônico.", "d": "Correta. O termo ''Hidrotórax Doce'' vem justamente da glicose elevada vinda do dialisado.", "e": "Incorreta. O dialisado é pobre em proteínas (transudato)."}, "difficulty": "dificil", "tags": ["Pneumologia", "Nefrologia", "Hidrotórax Doce", "Diálise Peritoneal"]}', 20, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Pleurite Crônica Não-Específica'' é um laudo comum de biópsia pleural que não detecta câncer ou TB. Qual a conduta recomendada se a suspeita clínica de malignidade for alta?", "options": {"a": "Fazer apenas gargarejos.", "b": "Tratar como pneumonia por 2 anos.", "c": "Repetir a investigação através de biópsia guiada por videotoracoscopia (VATS) para obter amostras maiores e mais representativas da pleura parietal e visceral.", "d": "Trocar o patologista.", "e": "Dar alta ao paciente."}, "answer": "c", "rationale": "Cerca de 30-40% das biópsias inespecíficas iniciais em pacientes com suspeita de câncer acabam revelando malignidade em investigações subsequentes mais invasivas. O acompanhamento rigoroso ou a cirurgia diagnóstica (VATS) são obrigatórios.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Fluxograma de investigação de pleura de origem indeterminada.", "d": "Incorreta. Embora a revisão de lâminas seja válida, a re-amostragem cirúrgica é o passo definitivo.", "e": "Incorreta. Negligência diagnóstica."}, "difficulty": "media", "tags": ["Pneumologia", "Diagnóstico", "Propedeutica", "Indeterminado"]}', 21, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 22 anos apresenta febre e derrame pleural linfocítico (88%). ADA de 45 U/L. Biópsia pleural de Abrams com granulomas e necrose de caseificação. Sobre a necessidade de isolamento respiratório para este paciente na enfermaria, assinale a correta.", "options": {"a": "Deve durar pelo menos 6 meses.", "b": "A biópsia pleural confirma que o paciente é altamente bacilífero.", "c": "Obrigatório para todos os pacientes com TB de qualquer sítio.", "d": "Desnecessário se o paciente não tiver lesão pulmonar parenquimatosa cavitária associada e se a baciloscopia de escarro for negativa.", "e": "O dreno de tórax aumenta o risco de contágio aéreo por aerolização."}, "answer": "d", "rationale": "A Tuberculose Pleural isolada não é considerada infectante, pois não há comunicação entre o espaço pleural e as vias aéreas para a produção de aerossóis bacilíferos. O isolamento só é necessário se houver Tuberculose Pulmonar concomitante (o que ocorre em cerca de 20-30% dos casos de TB pleural).", "option_rationales": {"a": "Incorreta. O isolamento termina após 15 dias de tratamento eficaz se a TB for pulmonar infectante.", "b": "Incorreta. A biópsia reflete o tecido pleural, não a carga bacilífera nas vias aéreas respiratórias.", "c": "Incorreta. TB extrapulmonar isolada (ex: pleural, óssea, ganglionar) não exige precauções para aerossóis.", "d": "Correta. Regra fundamental de isolamento hospitalar.", "e": "Incorreta. O dreno é um sistema fechado."}, "difficulty": "media", "tags": ["Pneumologia", "Infectologia", "Controle de Infecção", "Tuberculose"]}', 22, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Diferenciar um exsudato de um transudato é o passo fundamental na abordagem do derrame pleural. No entanto, os Critérios de Light podem classificar erroneamente até 25% dos transudatos como exsudatos. No caso de suspeita de falso-exsudato, qual dos seguintes parâmetros deve ser solicitado para auxiliar na diferenciação?", "options": {"a": "Densidade do líquido pleural < 1015.", "b": "Gradiente de LDH Soro-Pleura maior que 200 U/L.", "c": "Colesterol pleural < 45 mg/dL.", "d": "Gradiente de Proteína Total (Soro - Pleura) > 3,1 g/dL.", "e": "Bilirrubina pleural / Bilirrubina sérica < 0,5."}, "answer": "d", "rationale": "Quando os critérios de Light sugerem um exsudato, mas a clínica aponta fortemente para ICC ou Cirrose, usamos os gradientes. Um gradiente de Proteína Total (Soro - Pleura) maior que 3,1 g/dL ou um gradiente de Albumina maior que 1,2 g/dL favorecem o diagnóstico de transudato, mesmo com critérios de Light positivos.", "option_rationales": {"a": "Incorreta. A densidade é um parâmetro antigo e pouco preciso.", "b": "Incorreta. Não existe um critério amplamente validado de gradiente de LDH soro-pleura para isso.", "c": "Incorreta. Colesterol pleural > 45 mg/dL é um critério para exsudato, não transudato.", "d": "Correta. O gradiente de proteína > 3,1 g/dL indica transudato em casos de falso-exsudato pelo Light.", "e": "Incorreta. A relação de bilirrubina é um critério adicional para exsudato (se > 0,6), mas menos usado."}, "difficulty": "dificil", "tags": ["Pneumologia", "Derrame Pleural", "Critérios de Light", "Transudato"]}', 23, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a causa de derrame pleural volumoso à esquerda que apresenta níveis de lipase pleural superiores aos níveis séricos?", "options": {"a": "Câncer de Cólon.", "b": "Hérnia Diafragmática de Bochdalek infectada.", "c": "Pancreatite.", "d": "Ruptura de Baço.", "e": "Perfuração de Duodeno."}, "answer": "c", "rationale": "A amilase e a lipase pleurais elevadas são marcadores de patologia pancreática (pancreatite aguda ou pseudocisto). A enzima vaza para o espaço pleural pela via linfática transdiafragmática ou por fístulas.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Marcador bioquímico específico.", "d": "Incorreta. Baço não produz lipase digestiva.", "e": "Incorreta. Duodeno recebe lipase, mas sua ruptura dificilmente daria um derrame pleural isolado com este perfil sem um quadro abdominal catastrófico e amilase salivar."}, "difficulty": "facil", "tags": ["Pneumologia", "Bioquímica", "Pancreatite", "Lipase"]}', 24, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Pleurodese Espontânea'' ou ''Autopleurodese'' pode ocorrer em qual situação clínica, muitas vezes evitando a necessidade de intervenção cirúrgica?", "options": {"a": "Após uma única toracentese diagnóstica pequena.", "b": "No uso de amoxicilina oral.", "c": "Em pacientes tabagistas.", "d": "Sempre que houver transudato cardíaco.", "e": "Em pacientes com cateter pleural de demora (IPC), devido à inflamação crônica causada pelo trajeto do cateter e pela drenagem contínua do líquido."}, "answer": "e", "rationale": "Cerca de 40-50% dos pacientes que usam cateter pleural de demora (IPC) para derrame maligno acabam desenvolvendo sínfise pleural espontânea após alguns meses. Isso permite a retirada do cateter, pois o espaço pleural deixa de existir devido à reação inflamatória crônica ao corpo estranho e à aposição das pleuras.", "option_rationales": {"a": "Incorreta. Uma punção raramente causa sínfise.", "b": "Incorreta.", "c": "Incorreta. O tabaco causa enfisema, não pleurodese.", "d": "Incorreta. Transudatos não inflamam a pleura para causar sínfise.", "e": "Correta. Fenômeno observado em pacientes com dreno de longa permanência."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Cateter Pleural", "Pleurodese"]}', 25, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No manejo do derrame pleural neoplásico recorrente, a pleurodese química é uma opção comum. Qual a contraindicação PRINCIPAL para a realização de pleurodese?", "options": {"a": "Uso de quimioterapia há menos de 7 dias.", "b": "Idade superior a 80 anos.", "c": "Classificação do líquido como exsudato.", "d": "Presença de atelectasia obstrutiva sem reexpansão pulmonar após drenagem (Pulmão Encarcerado).", "e": "Volume de derrame superior a 1 litro."}, "answer": "d", "rationale": "Para que a pleurodese funcione, é necessário que as pleuras visceral e parietal entrem em contato após a drenagem para que o agente irritante (talco, nitrato, etc.) promova a sínfise. Se o pulmão estiver ''encarcerado'' (trapped lung) por tumor ou fibrose e não reexpandir, a pleurodese irá falhar invariavelmente.", "option_rationales": {"a": "Incorreta. A quimio não contraindica, embora possa reduzir a resposta inflamatória desejada.", "b": "Incorreta. Idade não impede, apenas exige cautela na dose de sedação.", "c": "Incorreta. Quase todos os derrames neoplásicos são exsudatos.", "d": "Correta. A ausência de reexpansão garante a falha do procedimento.", "e": "Incorreta. Volume alto não é contraindicação se o pulmão reexpandir."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Pleurodese", "Manejo"]}', 26, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 40 anos, proveniente de área rural da Ásia e residente no Brasil há 2 anos, apresenta-se com tosse crônica, hemoptise leve e dor torácica. A radiografia revela derrame pleural à direita e infiltrado pulmonar migratório. A análise do líquido pleural mostra um exsudato com 55% de eosinófilos, glicose de 15 mg/dL e LDH de 1.500 U/L. Qual o agente etiológico mais provável considerando a epidemiologia e o perfil bioquímico ''explosivo'' do líquido?", "options": {"a": "Ancylostoma duodenale.", "b": "Paragonimus westermani.", "c": "Schistosoma mansoni.", "d": "Toxocara canis (Larva Migrans Visceral).", "e": "Strongyloides stercoralis."}, "answer": "b", "rationale": "A paragonimíase (distomatose pulmonar) é uma causa clássica de derrame pleural eosinofílico que, paradoxalmente, apresenta bioquímica de empiema ou artrite reumatoide: glicose baixíssima (< 20 mg/dL) e LDH muito elevado. O contexto de paciente asiático com sintomas pleuropulmonares crônicos é altamente sugestivo.", "option_rationales": {"a": "Incorreta. Não apresenta tropismo pleural para causar exsudatos tão agressivos.", "b": "Correta. Perfil bioquímico patognomônico em contexto epidemiológico favorável.", "c": "Incorreta. O Schistosoma causa mais hipertensão pulmonar do que derrame eosinofílico com glicose baixa.", "d": "Incorreta. Causa eosinofilia periférica marcada, mas o derrame eosinofílico costuma ter glicose normal.", "e": "Incorreta. Estrongiloidíase disseminada causa pneumonia e SDRA, mas não derrame com este padrão bioquímico."}, "difficulty": "dificil", "tags": ["Pneumologia", "Infectologia", "Parasitoses", "Eosinofilia Pleural"]}', 27, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal limitação da citometria de fluxo no líquido pleural para o diagnóstico de Linfoma?", "options": {"a": "As células malignas do linfoma podem sofrer lise rápida se o transporte do líquido para o laboratório não for imediato e em frasco adequado.", "b": "Só funciona no sangue periférico.", "c": "Poucas células no líquido.", "d": "É muito cara.", "e": "Não consegue detectar linfócitos B."}, "answer": "a", "rationale": "Linfócitos neoplásicos são frágeis. O transporte inadequado ou a demora na análise podem destruir as células, levando a resultados falso-negativos na citometria de fluxo. O ideal é o processamento imediato ou uso de meio de conservação.", "option_rationales": {"a": "Correta. Limitação técnica e pré-analítica crítica.", "b": "Incorreta. Funciona muito bem em serosas (líquidos cavitários).", "c": "Incorreta. Linfomas pleurais costumam ser muito celulares.", "d": "Incorreta. Embora cara, a limitação biológica/técnica citada é mais relevante no diagnóstico falho.", "e": "Incorreta. Detecta perfeitamente através de marcadores de superfície (CD19, CD20, etc)."}, "difficulty": "media", "tags": ["Pneumologia", "Hematologia", "Linfoma", "Citometria"]}', 28, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "O gradiente de albumina (Soro - Líquido Pleural) é considerado o melhor teste para identificar transudatos cardíacos rotulados como exsudatos pelos critérios de Light. Qual valor de gradiente favorece o diagnóstico de Transudato?", "options": {"a": "< 1,2 g/dL", "b": "= 0", "c": "< 0,5 g/dL", "d": "> 1,2 g/dL", "e": "> 3,1 g/dL"}, "answer": "d", "rationale": "Um gradiente de albumina soro-pleura > 1,2 g/dL tem alta acurácia para identificar transudatos que parecem exsudatos devido ao uso de diuréticos (falsos exsudatos). O valor de 3,1 g/dL é usado para o gradiente de Proteína Total, não Albumina.", "option_rationales": {"a": "Incorreta. Favorece exsudato.", "b": "Incorreta. Fisicamente impossível.", "c": "Incorreta. Sugere exsudato verdadeiro.", "d": "Correta. Padrão de gradiente para ICC sob tratamento.", "e": "Incorreta. Este é o corte para Proteína Total."}, "difficulty": "media", "tags": ["Pneumologia", "Laboratório", "Gradiente de Albumina"]}', 29, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Mulher de 35 anos apresenta-se com quadro de endometriose pélvica conhecida. Durante o período menstrual, ela relata episódios recorrentes de dor torácica súbita e dispneia. O último episódio resultou em um derrame pleural hemorrágico à direita. A tomografia mostra pequenos nódulos pleurais e diafragmáticos com sinal de sangue agudo. Qual o diagnóstico?", "options": {"a": "Câncer de ovário com metástase pleural precoce.", "b": "Hemotórax espontâneo por ruptura de fístula arteriovenosa.", "c": "Linfangioleiomiomatose com hemoptise associada.", "d": "Tuberculose Pleural hemorrágica.", "e": "Endometriose Pleural (Hemotórax Catamenial)."}, "answer": "e", "rationale": "A endometriose torácica pode causar pneumotórax catamenial (mais comum), hemotórax catamenial ou hemoptise catamenial. A característica principal é a ciclicidade dos sintomas, coincidindo com o período menstrual (geralmente entre 24-48h do início da menstruação). O hemitórax direito é acometido em > 90% dos casos devido à circulação peritoneal rumo aos poros diafragmáticos direitos.", "option_rationales": {"a": "Incorreta. Metástases dariam sintomas constantes e progressivos.", "b": "Incorreta. Não explica a ciclicidade menstrual.", "c": "Incorreta. A LAM causa quilotórax e pneumotórax, não tipicamente hemotórax recorrente cíclico.", "d": "Incorreta. TB não é cíclica.", "e": "Correta. A ciclicidade e a localização à direita são marcos da endometriose torácica/pleural."}, "difficulty": "media", "tags": ["Pneumologia", "Ginecologia", "Endometriose Torácica", "Hemotórax"]}', 30, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em pacientes com ''Artroplastia de Quadril ou Joelho'' recente, a ocorrência de derrame pleural súbito bilateral com hipoxemia e rash petequial axilar sugere qual diagnóstico de exclusão?", "options": {"a": "Empiema hospitalar.", "b": "Síndrome da Embolia Gordurosa (SEG).", "c": "Tuberculose óssea.", "d": "Linfangiomatose.", "e": "Reação ao cimento ortopédico."}, "answer": "b", "rationale": "A SEG ocorre após trauma ou cirurgia de ossos longos/grandes articulações. Os glóbulos de gordura atingem o pulmão desencadeando uma cascata inflamatória grave (pneumonite gordurosa) que pode cursar com derrames pleurais exsudativos e sofrimento respiratório agudo.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Quadro clínico-cirúrgico clássico em ortopedia/pneumo.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Ortopedia", "Embolia Gordurosa", "Derrame Pleural"]}', 31, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 68 anos, portador de insuficiência cardíaca e doença renal crônica, apresenta-se com derrame pleural bilateral. A análise do líquido pleural revela: Proteína 2,9 g/dL (Sérica 6,0 g/dL), LDH 190 U/L (Sérico 420 U/L - limite superior do soro 450 U/L). Pelos critérios de Light, o líquido é classificado como exsudato (Prot P/S > 0,5). No entanto, a dosagem de NT-proBNP no líquido pleural é de 3.200 pg/mL. Qual a interpretação mais provável?", "options": {"a": "Pleurite urêmica aguda.", "b": "Derrame cardíaco rotulado como exsudato falso-positivo pelos critérios de Light (frequentemente devido ao uso de diuréticos).", "c": "Tuberculose pleural paucibacilar.", "d": "Derrame pleural maligno oculto.", "e": "Empiema bacteriano na fase inicial."}, "answer": "b", "rationale": "Em pacientes com ICC usando diuréticos, os critérios de Light podem falhar (especialmente a relação de proteínas). Um NT-proBNP pleural > 1.500 pg/mL tem altíssima especificidade para origem cardíaca, sendo o melhor marcador para desmentir um falso exsudato do Light nestes casos.", "option_rationales": {"a": "Incorreta. Pleurite urêmica é um exsudato real (fibrinoso/linfocítico), não explicaria o NT-proBNP tão alto sem falha cardíaca associada.", "b": "Correta. Aplicação clássica de biomarcadores cardíacos no líquido pleural.", "c": "Incorreta. TB teria ADA alto e não elevaria NT-proBNP.", "d": "Incorreta. O NT-proBNP alto aponta para a via cardíaca.", "e": "Incorreta. Empiema teria pH baixo e neutrofilia."}, "difficulty": "media", "tags": ["Pneumologia", "Bioquímica", "ICC", "NT-proBNP"]}', 32, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual dos seguintes parâmetros no líquido pleural ajuda a diferenciar um hemotórax verdadeiro de uma toracentese traumática (acidente de punção)?", "options": {"a": "Presença de leucócitos > 10.000.", "b": "LDH pleural < 200 U/L.", "c": "Presença de eosinofilia > 10%.", "d": "Hematócrito pleural > 50% do hematócrito periférico.", "e": "Ausência de plaquetas no líquido."}, "answer": "d", "rationale": "Um hemotórax é definido por um hematócrito no líquido pleural de pelo menos 50% do hematócrito sanguíneo do paciente. Se o hematócrito pleural for baixo, trata-se apenas de um derrame sero-hemorrágico ou contaminação por sangue durante o procedimento.", "option_rationales": {"a": "Incorreta. Indica infecção.", "b": "Incorreta. Líquidos hemorrágicos têm LDH alto.", "c": "Incorreta. Sangue na pleura dá eosinofilia, mas não diferencia a origem aguda.", "d": "Correta. Critério diagnóstico clássico de hemotórax.", "e": "Incorreta. As plaquetas tendem a se agregar e sumir da contagem automática no líquido pleural em ambos os casos."}, "difficulty": "facil", "tags": ["Pneumologia", "Hemotórax", "Diagnóstico"]}', 33, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico da etiologia do derrame pleural, o achado de células de câncer no líquido pleural em um paciente com tumor de pulmão conhecido confere qual estádio T N M?", "options": {"a": "Tis.", "b": "T4.", "c": "M1b.", "d": "M1a.", "e": "N3."}, "answer": "d", "rationale": "De acordo com o sistema TNM (8ª edição) para câncer de pulmão, a presença de nódulos pleurais ou pericárdicos malignos ou de derrames pleural/pericárdico malignos é classificada como estádio M1a (doença metastática intratorácica), conferindo automaticamente o estágio IV.", "option_rationales": {"a": "Incorreta. Carcinoma in situ.", "b": "Incorreta. T4 seria invasão de grandes vasos ou esôfago, mas não disseminação pleural livre por células no líquido.", "c": "Incorreta. M1b é metástase extratorácica única.", "d": "Correta. Critério de disseminação pleural metastática intratorácica.", "e": "Incorreta. Reflete comprometimento de linfonodos cervicais ou contralaterais."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "TNM", "Estadiamento"]}', 34, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A presença de ''linfangite carcinomatosa'' na radiografia e TC de tórax (espessamento nodular de septos interlobulares) em um paciente com derrame pleural maligno unilateral, aponta para qual mecanismo adicional de formação do líquido?", "options": {"a": "Bloqueio da drenagem linfática pleural e pulmonar retrógrada.", "b": "Hipotireoidismo paraneoplásico.", "c": "Redução acentuada da permeabilidade capilar.", "d": "Invasão direta do esôfago pelo tumor.", "e": "Aumento da pressão hidrostática arterial."}, "answer": "a", "rationale": "A linfangite carcinomatosa reflete a invasão dos vasos linfáticos pulmonares por células neoplásicas. Isso causa um bloqueio mecânico severo à drenagem linfática pleural, que é a principal via de saída de líquido e proteínas. O resultado é um derrame volumoso, recidivante e de difícil controle clínico.", "option_rationales": {"a": "Correta. Mecanismo principal de derrames neoplásicos de grandes volumes.", "b": "Incorreta. Hipotireoidismo não causa linfangite radiológica.", "c": "Incorreta. O câncer aumenta a permeabilidade.", "d": "Incorreta. Daria derrame purulento/alimentar.", "e": "Incorreta. Mecanismo de transudato cardíaco."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Linfangite Carcinomatosa", "Fisiopatologia"]}', 35, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"options": {"a": "Posição Ortostática (Em pé).", "b": "Decúbito Dorsal com pernas elevadas.", "c": "Decúbito Lateral Esquerdo e Trendelenburg (Posição de Durant).", "d": "Posição de Fowler (Sentado).", "e": "Pronação imediata."}, "answer": "c", "rationale": "A posição de Durant (decúbito lateral esquerdo + Trendelenburg) visa manter a bolha de ar no ápice do ventrículo direito ou átrio direito, impedindo que ela entre na artéria pulmonar (no caso de embolia venosa) ou favorecendo a flutuação para longe da circulação cerebral (no caso de embolia arterial retrógrada via fencas).", "option_rationales": {"a": "Incorreta. Perigoso.", "b": "Incorreta. Não ajuda a aprisionar a bolha de ar no coração.", "c": "Correta. Manobra clássica de emergência para embolia gasosa.", "d": "Incorreta. Favorece a migração de ar para o cérebro.", "e": "Incorreta. Inútil."}, "difficulty": "dificil", "tags": ["Pneumologia", "Procedimentos", "Complicações", "Embolia Gasosa"], "enunciado": "A embolia gasosa durante a toracentese é uma complicação rara, mas catastrófica. Qual deve ser a posição imediata do paciente se houver suspeita de embolia gasosa iatrogênica durante o procedimento?"}', 36, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Biópsia Pleural por Agulha'' é contraindicada ou apresenta risco inaceitável em qual das seguintes situações?", "options": {"a": "Uso de oxigênio por cateter nasal.", "b": "Presença de loculações pleurais.", "c": "Derrame pleural muito pequeno (lâmina de líquido < 1 cm na radiografia de Laurell) sem guia de imagem.", "d": "Idade inferior a 18 anos.", "e": "Paciente com febre acima de 39°C."}, "answer": "c", "rationale": "Puncionar a pleura com agulha de biópsia (que tem uma abertura cortante lateral) quando há pouco líquido coloca o pulmão e o diafragma em risco imediato de laceração. Exige técnica guiada por imagem (US ou TC) ou drenagem prévia/preenchimento com ar em técnicas antigas hoje obsoletas.", "option_rationales": {"a": "Incorreta. Paciente hipoxêmico pode e deve ser diagnosticado.", "b": "Incorreta. Pode ser feita guiada por imagem justamente na loculação.", "c": "Correta. Regra de segurança em procedimentos invasivos cegos.", "d": "Incorreta. Crianças podem ser biopsiadas.", "e": "Incorreta. Febre não contraindica a biópsia diagnóstica."}, "difficulty": "media", "tags": ["Pneumologia", "Procedimentos", "Segurança", "Contraindicações"]}', 37, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente tabagista pesado desenvolve derrame pleural hemorrágico unilateral. A citologia oncótica e duas biópsias de Abrams foram negativas para malignidade. O paciente apresenta também um nódulo na glândula adrenal direita evidenciado na TC. Qual a conduta diagnóstica mais lógica a seguir?", "options": {"a": "Realizar terceira biópsia de Abrams no mesmo hemitórax.", "b": "Tratamento empírico para Tuberculose com esquema RIPE.", "c": "Pet-CT e acompanhamento radiológico em 6 meses.", "d": "Biópsia por agulha guiada por TC da glândula adrenal.", "e": "Videotoracoscopia imediata e pleurodese."}, "answer": "d", "rationale": "Em casos de suspeita de câncer de pulmão metastático (derrame + nódulo adrenal), a biópsia da metástase presumida (adrenal) é frequentemente mais fácil e fornece tanto o diagnóstico histológico quanto o estadiamento (M1b) simultaneamente, evitando procedimentos torácicos mais invasivos se a adrenal for positiva.", "option_rationales": {"a": "Incorreta. O rendimento marginal seria baixo.", "b": "Incorreta. Sem evidências de TB e com forte suspeita de neoplasia.", "c": "Incorreta. O acompanhamento de 6 meses é perigoso em neoplasias agressivas.", "d": "Correta. Estratégia de ''atirar no alvo mais fácil'' para diagnóstico e estadiamento.", "e": "Incorreta. A biópsia da adrenal pode poupar o paciente de uma cirurgia torácica diagnóstica."}, "difficulty": "dificil", "tags": ["Pneumologia", "Oncologia", "Estadiamento", "Biópsia Adrenal"]}', 38, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No ultrassom de tórax, a presença do ''Sinal do Plâncton'' (Plankton Sign) — partículas flutuantes e móveis dentro do líquido pleural — sugere fortemente qual natureza do derrame?", "options": {"a": "Cisto hidático roto.", "b": "Transudato simples (água pura).", "c": "Pneumotórax.", "d": "Líquido rico em detritos celulares, proteínas ou sangue (ex: empiema, hemotórax ou derrame maligno).", "e": "Derrame de colesterol apenas."}, "answer": "d", "rationale": "Líquidos anecoicos (pretos) no US costumam ser transudatos. Quando há ecogenicidade interna (pontos brilhantes que se movem como plâncton), isso indica um exsudato com alta celularidade ou conteúdo proteico/hemático, ajudando o clínico a guiar a suspeita diagnóstica antes mesmo da bioquímica.", "option_rationales": {"a": "Incorreta. Cisto hidático tem membranas flutuantes (''sinal do lírio d''água''), não plâncton fino.", "b": "Incorreta. Transudatos são tipicamente anecoicos e ''limpos''.", "c": "Incorreta. Pneumotórax impede a visualização de líquido.", "d": "Correta. Marcador ultrassonográfico de exsudato complexo.", "e": "Incorreta. Derrame de colesterol tem cristais que dão um padrão de ''neve'' (snowstorm), mas o plâncton é mais geral para qualquer exsudato turvo."}, "difficulty": "media", "tags": ["Pneumologia", "Ultrassonografia", "Semiologia", "Exsudato"]}', 39, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Manometria Pleural'' é uma técnica utilizada durante a toracocentese para medir a pressão no espaço pleural. Qual o principal objetivo clínico desta medição?", "options": {"a": "Identificar precocemente o ''Pulmão Encarcerado'' (através da medida da elastância pleural elevada) e prevenir o edema de reexpansão ou dor intratável durante a drenagem.", "b": "Substituir a radiografia de tórax.", "c": "Diagnosticar asma.", "d": "Calibrar o ventilador mecânico.", "e": "Verificar se o paciente está com soluços."}, "answer": "a", "rationale": "A manometria mede a queda da pressão pleural à medida que o líquido é removido. Se a pressão cair muito rápido (alta elastância), significa que o pulmão não consegue expandir para preencher o espaço (encarceramento). Isso alerta o médico para interromper o procedimento antes que ocorra laceração pulmonar ou edema de reexpansão grave.", "option_rationales": {"a": "Correta. Utilidade fisiológica aplicada à segurança do procedimento.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Pneumologia", "Procedimentos", "Manometria Pleural", "Fisiologia"]}', 40, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ocorrência de derrame pleural volumoso ''marrom escuro'' ou ''achocolatado'' após um trauma hepático ou em um paciente com abscesso hepático amebiano sugere fístula hepatopleural. Qual o agente causal clássico?", "options": {"a": "Trypanosoma cruzi.", "b": "Entamoeba histolytica.", "c": "Schistosoma hematobium.", "d": "Ascaris lumbricoides.", "e": "Giardia lamblia."}, "answer": "b", "rationale": "O abscesso amebiano hepático pode romper para o espaço pleural (geralmente à direita). O líquido é classicamente descrito como ''pasta de anchovas'' ou ''achocolatado'', composto de tecido hepático necrótico e sangue digerido. É uma complicação grave da amebíase extraintestinal.", "option_rationales": {"a": "Incorreta. Causa miocardite/megaesôfago.", "b": "Correta. Agente da amebíase invasiva hepática/pleural.", "c": "Incorreta. Acomete sistema urinário.", "d": "Incorreta. Causa ciclo de Loeffler no parênquima, não abscessos achocolatados.", "e": "Incorreta. Não causa abscessos hepáticos ou derrames."}, "difficulty": "facil", "tags": ["Pneumologia", "Infectologia", "Amebíase", "Abscesso Hepático"]}', 41, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"options": {"a": "Pneumonia pneumocócica com empiema.", "b": "Mesotelioma pleural maligno.", "c": "Linfoma não-Hodgkin.", "d": "Cirrose alcoólica Child-Pugh C.", "e": "Sarcoidose multissistêmica."}, "answer": "c", "rationale": "O achado de triglicerídeos > 110 mg/dL e aspecto leitoso confirma Quilotórax. Em adultos, a causa não-traumática mais comum de quilotórax é a obstrução do ducto torácico por neoplasia, sendo o Linfoma a etiologia predominante. A presença de linfonodomegalia cervicorretroperitoneal reforça fortemente essa hipótese.", "option_rationales": {"a": "Incorreta. Empiema é purulento (leucócitos), não quiloso (gordura).", "b": "Incorreta. Mesotelioma causa derrame neoplásico citológico ou hemorrágico, raramente quiloso.", "c": "Correta. Linfoma é a causa principal de quilotórax não-traumático no adulto.", "d": "Incorreta. Cirrose dá transudato e raramente quilotórax (apenas se houver fístula de linfa).", "e": "Incorreta. Sarcoidose raramente causa quilotórax."}, "difficulty": "dificil", "tags": ["Pneumologia", "Linfoma", "Quilotórax", "Hematologia"], "enunciado": "Paciente masculino, 55 anos, em investigação de ascite e derrame pleural esquerdo volumoso. A análise do líquido pleural mostra: Exsudato, TG = 500 mg/dL, aspecto leitoso. Radiografia mostra espessamento de linfonodos cervicais e retroperitoneais. Qual a patologia mais provável que une esses achados?"}', 42, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente de 60 anos com quadro de ascite e derrame pleural exsudativo linfocítico unilateral. RX mostra nódulo pulmonar espiculado. Qual a sensibilidade aproximada da citologia oncótica do líquido pleural para o diagnóstico de malignidade em uma primeira amostra bem coletada?", "options": {"a": "Entre 80% e 95%.", "b": "Menos de 20%.", "c": "Entre 50% e 65%.", "d": "Próxima de 100%.", "e": "0%, pois a biópsia é sempre necessária."}, "answer": "c", "rationale": "A sensibilidade da primeira amostra de citologia oncótica gira em torno de 50-60%. Se uma segunda amostra for enviada, a sensibilidade sobe para cerca de 75-80%. Amostras adicionais após a segunda trazem ganho marginal de diagnóstico, sendo indicada a biópsia se a dúvida persistir.", "option_rationales": {"a": "Incorreta. Valor alcançado apenas após várias amostras ou em casos específicos de adenocarcinoma avançado.", "b": "Incorreta. A citologia é um excelente exame inicial, com rendimento razoável.", "c": "Correta. Faixa de sensibilidade clássica da primeira toracentese.", "d": "Incorreta. Frequentemente a citologia é falha na primeira amostra.", "e": "Incorreta. A citologia muitas vezes descarta a necessidade de biópsia invasiva."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Diagnóstico", "Citologia"]}', 43, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A Pleurite Bacteriana Espontânea (SBPE) é uma complicação da cirrose hepática com hidrotórax hepático. Qual o critério diagnóstico para SBPE na análise do líquido pleural?", "options": {"a": "Presença de pus franco no espaço pleural.", "b": "Contagem de Polimorfonucleares (PMN) > 250 células/mm³ com cultura positiva ou PMN > 500 células/mm³ se a cultura for negativa (excluindo empiema de causa pulmonar).", "c": "pH pleural < 7,10 em todas as amostras.", "d": "Dosagem de amilase pleural 3x maior que a sérica.", "e": "Proteína total pleural > 3,0 g/dL."}, "answer": "b", "rationale": "A SBPE é o equivalente pleural da Peritonite Bacteriana Espontânea (PBE). Ocorre em pacientes cirróticos com hidrotórax preexistente. O diagnóstico é baseado na celularidade (PMN > 250 ou 500) e na exclusão de um foco infeccioso pulmonar (pneumonia) adjacente, que caracterizaria um derrame parapneumônico e não SBPE.", "option_rationales": {"a": "Incorreta. Pus franco indica empiema estabelecido, não a forma ''espontânea'' do cirrótico.", "b": "Correta. Critério análogo ao da PBE adaptado para a pleura.", "c": "Incorreta. O pH pode não atingir valores tão baixos na fase inicial.", "d": "Incorreta. Amilase alta indica causa pancreática ou ruptura esofágica.", "e": "Incorreta. O hidrotórax hepático é classicamente transudato (proteína baixa)."}, "difficulty": "dificil", "tags": ["Pneumologia", "Gastroenterologia", "Cirrose", "SBPE"]}', 44, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente de 70 anos, tabagista inveterado, apresenta derrame pleural volumoso à esquerda. A toracentese revela líquido hemorrágico (Hto pleural / Hto periférico = 15%). A citologia oncótica é negativa em duas amostras. O pulmão não expande completamente após a drenagem esvaziadora (pulmão encarcerado). Qual a conduta recomendada para paliação do sintoma de dispneia neste caso?", "options": {"a": "Toracocenteses de alívio mensais conforme a dispneia.", "b": "Inserção de cateter pleural de demora (PleurX ou similar).", "c": "Pleurectomia parietal por videotoracoscopia (VATS).", "d": "Realizar pleurodese química com talco via dreno de tórax.", "e": "Encaminhamento para radioterapia de pleura."}, "answer": "b", "rationale": "O ''pulmão encarcerado'' (trapped lung) ocorre quando a pleura visceral está espessada e impede a expansão pulmonar. Nesses casos, a pleurodese falha porque não há contato entre as pleuras. O cateter pleural de demora é a melhor opção paliativa, permitindo a drenagem domiciliar conforme a necessidade do paciente.", "option_rationales": {"a": "Incorreta. Toracocenteses de repetição causam desconforto e risco de infecção maior que o cateter.", "b": "Correta. O cateter de demora é indicado especificamente para pulmão encarcerado neoplásico.", "c": "Incorreta. A pleurectomia é uma cirurgia de grande porte, raramente indicada para paliação em idosos com doença avançada.", "d": "Incorreta. A pleurodese exige reexpansão pulmonar completa para funcionar.", "e": "Incorreta. A radioterapia não é tratamento para derrame pleural volumoso."}, "difficulty": "dificil", "tags": ["Pneumologia", "Oncologia", "Derrame Pleural Maligno", "Pulmão Encarcerado"]}', 45, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 40 anos apresenta derrame pleural bilateral assintomático, ascite e edema de membros inferiores. A análise do líquido pleural é um transudato. A dosagem de albumina sérica é de 1,6 g/dL e a proteinúria de 24 horas é de 12 gramas. Qual a causa do derrame pleural?", "options": {"a": "Insuficiência Cardíaca Congestiva.", "b": "Cirrose Hepática.", "c": "Síndrome Nefrótica.", "d": "Tuberculose Peritoneal.", "e": "Sarcoidose Sistêmica."}, "answer": "c", "rationale": "A proteinúria maciça (> 3,5g/dia) e a hipoalbuminemia grave definem a síndrome nefrótica. O derrame pleural ocorre pela queda drástica da pressão oncótica plasmática, permitindo a transudação de líquido para o espaço pleural (frequentemente bilateral e associado a anasarca).", "option_rationales": {"a": "Incorreta. ICC causa derrame, mas não explica a perda urinária de proteína.", "b": "Incorreta. Cirrose daria ascite desproporcional e albumina baixa, mas não proteinúria de 12g.", "c": "Correta. Quadro laboratorial clássico de necrose glomerular/síndrome nefrótica.", "d": "Incorreta. TB seria exsudato.", "e": "Incorreta. Sarcoidose pode dar nefrite, mas o quadro nefrótico franco com transudato pleural não é sua manifestação principal."}, "difficulty": "facil", "tags": ["Pneumologia", "Nefrologia", "Transudato", "Síndrome Nefrótica"]}', 46, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A dosagem de Soluble Mesothelin-Related Peptides (SMRP) no líquido pleural é um biomarcador promissor para o diagnóstico de qual patologia?", "options": {"a": "Artrite Reumatoide.", "b": "Cancer de Próstata.", "c": "Mesotelioma Maligno.", "d": "Pneumonia por Legionella.", "e": "Tuberculose Pleural."}, "answer": "c", "rationale": "O SMRP é liberado por células mesoteliais neoplásicas. Embora sua sensibilidade não seja perfeita, altos níveis no líquido pleural têm alta especificidade para o mesotelioma epitelioide.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Biomarcador específico para neoplasia mesotelial.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Biomarcadores", "Mesotelioma", "SMRP"]}', 47, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Pseudotumefação Pleural'' ou ''Tumor Evanescente'' no raio-X de tórax, associado à insuficiência cardíaca congestiva, localiza-se preferencialmente em qual estrutura anatômica?", "options": {"a": "Ângulo cardiofrênico esquerdo.", "b": "Cisura horizontal (pequena cisura).", "c": "Ápice pulmonar.", "d": "Seio costofrênico posterior.", "e": "Espaço retroesternal."}, "answer": "b", "rationale": "O tumor fantasma ou evanescente é o acúmulo de líquido loculado dentro de uma cisura pulmonar (mais comum na horizontal, à direita). Ao RX, a imagem biconvexa mimetiza uma massa sólida pulmonar, mas ''desaparece'' rapidamente após o tratamento com diuréticos.", "option_rationales": {"a": "Incorreta. Local de coxim gorduroso ou cistos pericárdicos.", "b": "Correta. Localização anatômica clássica dessa variante radiológica.", "c": "Incorreta. Raro localização de derrames por gravidade.", "d": "Incorreta. Localização de derrames livres habituais.", "e": "Incorreta. Localização de massas mediastinais."}, "difficulty": "media", "tags": ["Pneumologia", "Radiologia", "ICC", "Semiologia Radiológica"]}', 48, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a relação correta entre o lado do derrame e a patologia causal para as seguintes condições?", "options": {"a": "Derrame por Tuberculose: Sempre Bilateral.", "b": "Derrame por Ruptura de Ducto Torácico (abaixo de T5): Frequentemente à Direita.", "c": "Derrame por Artrite Reumatoide: Frequentemente Bilateral.", "d": "Derrame por Pancreatite: Frequentemente à Direita.", "e": "Derrame por ICC: Frequentemente Unilateral Esquerdo."}, "answer": "b", "rationale": "O ducto torácico cruza da direita para a esquerda ao nível de T4-T5. Lesões abaixo deste nível resultam em quilotórax à direita. Acima de T5, resultam em quilotórax à esquerda. A pancreatite costuma dar derrame à esquerda. ICC costuma ser bilateral ou à direita.", "option_rationales": {"a": "Incorreta. TB é classicamente unilateral.", "b": "Correta. Anatomia clássica do ducto torácico.", "c": "Incorreta. Mais comumente unilateral (75-80% dos casos de AR são unilaterais).", "d": "Incorreta. Pancreatite é predominantemente à esquerda.", "e": "Incorreta. ICC é bilateral ou direita (pela maior drenagem linfática à direita)."}, "difficulty": "dificil", "tags": ["Pneumologia", "Anatomia", "Topografia dos Derrames"]}', 49, 'draft');
